export const DEFAULT_ACCOUNT_TIME_ZONE = 'UTC';

/**
 * Turn an IANA name or alias into the canonical name the runtime recognizes.
 *
 * `Intl` is the same timezone database used for flight clocks. Asking it to
 * resolve the name avoids maintaining a second, drifting allowlist while still
 * rejecting arbitrary strings before they reach the account row.
 */
export function normalizeAccountTimeZone(value: string): string | null {
    const candidate = value.trim();
    if (candidate.length === 0 || candidate.length > 100) return null;

    try {
        return new Intl.DateTimeFormat('en-US', { timeZone: candidate })
            .resolvedOptions().timeZone;
    } catch {
        return null;
    }
}

/** Every runtime-supported customer choice, plus the explicit UTC fallback. */
export function accountTimeZoneChoices(): string[] {
    return [
        DEFAULT_ACCOUNT_TIME_ZONE,
        ...Intl.supportedValuesOf('timeZone').filter(zone => zone !== DEFAULT_ACCOUNT_TIME_ZONE),
    ];
}

/** An account instant in the timezone the customer chose, with the zone named. */
export function formatAccountDateTime(
    value: Date | string,
    timeZone: string,
): string {
    const zone = normalizeAccountTimeZone(timeZone) ?? DEFAULT_ACCOUNT_TIME_ZONE;
    return new Intl.DateTimeFormat('en-US', {
        day: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        month: 'long',
        timeZone: zone,
        timeZoneName: 'short',
        year: 'numeric',
    }).format(new Date(value));
}
=====BOOKING ITINERARY=====
/**
 * Reading a booking's flights through its legs.
 *
 * A booking is its own itinerary (#109), and since #118 it can hold more than
 * one leg. Every read of a booking's flights goes through here so that ordering
 * is applied in one place.
 *
 * The Prisma include has to load the legs and their flights:
 *
 *     include: { legs: {
 *         where: activeItineraryLegWhere,
 *         include: { flight: true },
 *         orderBy: { sequence: 'asc' },
 *     } }
 */

/** The shape these need, kept structural so callers can pass richer rows. */
export interface BookingLegs<TFlight> {
    legs: Array<{
        sequence: number;
        flight: TFlight | null;
        supersededAt?: Date | string | null;
    }>;
}

/** The database half of the active-leg rule, shared by every relation read. */
export const activeItineraryLegWhere = { supersededAt: null } as const;

/**
 * The legs of a booking in itinerary order.
 *
 * Historical legs stay attached to the booking after a rebooking. Filter them
 * here as a final product-code guard, then sort rather than trusting the query:
 * a caller that forgets either database clause must not render two flights at
 * the same itinerary position or put the return first.
 */
export function orderedLegs<TLeg extends {
    sequence: number;
    supersededAt?: Date | string | null;
}>(
    booking: { legs: TLeg[] }
): TLeg[] {
    return booking.legs
        .filter(leg => leg.supersededAt === undefined || leg.supersededAt === null)
        .sort((left, right) => left.sequence - right.sequence);
}

/**
 * The flights of a booking, in leg order. A leg whose flight was not loaded is
 * skipped rather than yielding a hole in the itinerary.
 */
export function bookingFlights<TFlight>(booking: BookingLegs<TFlight>): TFlight[] {
    return orderedLegs(booking)
        .map(({ flight }) => flight)
        .filter((flight): flight is TFlight => flight !== null && flight !== undefined);
}

interface HeldSeat {
    passengerId: string;
    seatNumber: string;
    cabinClass: string;
    /// Set once the seat was let go. Carried through so a reader can tell a
    /// live seat from one somebody else may now hold: the row keeps the real
    /// number either way (#76).
    releasedAt?: Date | string | null;
}

/**
 * Travellers described by where they sit on one particular leg.
 *
 * A traveller belongs to a booking, but a seat belongs to a flight, so any view
 * of a single flight -- a manifest, a seat map -- has to take the seat from that
 * leg's assignment. `Passenger.seatNumber` answers with the outbound seat
 * whichever leg is being looked at, which is wrong for every leg but the first.
 *
 * Reads only the assignment. The fallback to `Passenger.seatNumber` that stood
 * in for bookings taken before #118 is gone: that column describes the outbound
 * leg, so it was the wrong answer for every leg but the first (#137).
 */
export function passengersSeatedOnLeg<TPassenger extends { id: string }>(
    leg: { seatAssignments: HeldSeat[] },
    passengers: TPassenger[]
): Array<TPassenger & { seatNumber: string; releasedAt: Date | string | null; cabinClass: string }> {
    return passengers.map((passenger) => {
        const held = leg.seatAssignments.find((seat) => seat.passengerId === passenger.id);
        return {
            ...passenger,
            // Every traveller holds an assignment on every leg, asserted against
            // the whole table by seatAssignmentCoverage.database.test.ts. A leg
            // with no seat for someone is a defect, not a shape to render.
            // Empty rather than the words "Not assigned": the only reader
            // renders this through `seatLabel`, which says so properly. The
            // string used to be interpolated into "Seat Not assigned" (#229).
            seatNumber: held?.seatNumber ?? '',
            releasedAt: held?.releasedAt ?? null,
            cabinClass: held?.cabinClass ?? 'ECONOMY',
        };
    });
}

/**
 * How a seat reads to the customer.
 *
 * A released seat says so rather than showing a number, because the number is
 * no longer the customer's — somebody else may be sitting in it. It reads the
 * release rather than the seat number: releasing used to overwrite the number
 * with a `CANCELLED-` placeholder, so this had to recognise the placeholder and
 * a real seat number beginning with those letters would have been mistaken for
 * one (#76).
 */
export function seatLabel(
    seat: { seatNumber: string; releasedAt?: Date | string | null } | null | undefined,
): string {
    if (!seat?.seatNumber) return 'No seat assigned';
    // Named, not just numbered. "11A" beside a traveller's name is a seat only
    // if you already know that; a screen reader announced it as a bare
    // parenthetical, and a sighted reader had to infer it too (#229). The admin
    // manifest said "Seat 11A" for a held seat but a bare "Released" for a
    // let-go one; both now read this, so the two surfaces cannot drift.
    return seat.releasedAt ? 'Seat released' : `Seat ${seat.seatNumber}`;
}

const CABIN_NAMES: Record<string, string> = {
    ECONOMY: 'Economy',
    PREMIUM_ECONOMY: 'Premium Economy',
    BUSINESS: 'Business',
    FIRST: 'First Class',
};

/**
 * How a cabin reads to a customer.
 *
 * The enum was printed straight onto the boarding pass, so an e-ticket said
 * `PREMIUM_ECONOMY` — underscore, capitals and all — on the one artefact people
 * keep and show at an airport (#169).
 *
 * An unrecognised value is made readable rather than passed through, so a cabin
 * added to the schema before this map catches up still cannot reach a ticket
 * shouting in snake case. It is only ever a fallback: a real cabin belongs
 * above, where the wording is chosen rather than derived.
 */
export function cabinLabel(cabinClass: string | null | undefined): string {
    if (!cabinClass) return '';
    return CABIN_NAMES[cabinClass] ?? cabinClass
        .toLowerCase()
        .split('_')
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
}

/**
 * Names a leg by its direction, wherever one is labelled.
 *
 * "Returning" is only true of the *last* leg of a there-and-back trip, which is
 * all `MAX_ITINERARY_LEGS` permits today. Checkout and the profile each held
 * their own `index === 0 ? 'Departing' : 'Returning'`, which agreed only
 * because of that cap: connecting itineraries (#131) raise it, and the two
 * screens would then have called one flight different things (#160).
 *
 * It lives beside `seatLabel` because both answer the same kind of question:
 * how a piece of an itinerary reads to a customer.
 *
 * This covers the places that *label* a leg. Two seat-validation messages still
 * build their own lowercase "departing"/"returning" inline, because they read as
 * prose in a sentence rather than as a label and cannot take these strings as
 * they stand (#171).
 */
export function legDirectionLabel(legIndex: number, legCount: number): string {
    if (legIndex === 0) return 'Departing';
    if (legIndex === legCount - 1) return 'Returning';
    return `Leg ${legIndex + 1}`;
}

/**
 * The outbound flight, which is what every single-flight view wants today.
 * Null when the booking has no legs, or none whose flight was loaded.
 */
export function outboundFlight<TFlight>(booking: BookingLegs<TFlight>): TFlight | null {
    return bookingFlights(booking)[0] ?? null;
}

import { airportTimeZoneFor } from './airports';

/**
 * When a flight leaves, in the only two forms that are ever correct: an instant
 * to compare, and an airport's local reading to show.
 *
 * `Flight.departureDate` used to be neither. `FlightScheduleService` built it
 * from the schedule's local time with a `Z` stapled on -- 08:00 in Tokyo stored
 * as 08:00Z, which is 17:00 in Tokyo -- and every screen rendered it with
 * `toLocaleDateString()`, in whatever timezone the viewer's browser happened to
 * be in. Two errors that cancel only for a viewer in UTC looking at a UTC
 * airport, which is why they survived so long (#84).
 *
 * The comparisons cared as much as the displays. #76's cancellation guard
 * refuses a booking whose flight has departed; east of UTC it was wrong by the
 * origin's offset, leaving hours in which a flown flight could still be
 * cancelled -- releasing a seat that was used and taking back the points for a
 * trip the customer took.
 *
 * Everything here goes through `Intl`, which carries the IANA database and its
 * history of transitions, so a fixed offset per airport is never assumed.
 */

/**
 * How far the zone is from UTC at a given instant, in milliseconds.
 *
 * Read by asking `Intl` what the wall clock says there and subtracting: there
 * is no API that answers directly, and hard-coding offsets would be wrong twice
 * a year for most of the world.
 */
function zoneOffsetMs(timeZone: string, instant: Date): number {
    const parts = new Intl.DateTimeFormat('en-US', {
        timeZone,
        hour12: false,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    }).formatToParts(instant);

    const at = (type: Intl.DateTimeFormatPartTypes) =>
        Number(parts.find(part => part.type === type)!.value);

    // `hour` comes back as 24 at midnight under hour12: false, which Date.UTC
    // rolls into the next day -- correct arithmetic, wrong day.
    const asIfUtc = Date.UTC(
        at('year'), at('month') - 1, at('day'), at('hour') % 24, at('minute'), at('second'),
    );
    return asIfUtc - instant.getTime();
}

/**
 * The instant at which a wall clock reads `date` `time` at that airport.
 *
 * Two passes, because the offset depends on the instant and the instant depends
 * on the offset. The first pass guesses using the offset in force at the same
 * wall clock read as UTC; the second corrects it using the offset actually in
 * force at the guessed instant. That is exact everywhere except inside a
 * daylight-saving transition, where the answer is a choice rather than a fact:
 *
 *   * A wall clock the change *skips* (02:30 on a spring-forward morning) never
 *     happens. This lands just after the gap rather than throwing -- a schedule
 *     that names it is a data problem, not a reason to fail a page.
 *   * A wall clock the change *repeats* (01:30 on an autumn morning) happens
 *     twice. This takes the earlier, which is the conventional reading and the
 *     only one a schedule can mean without saying which.
 */
export function airportLocalInstant(date: string, time: string, timeZone: string): Date {
    const asIfUtc = Date.parse(`${date}T${time}:00.000Z`);
    if (Number.isNaN(asIfUtc)) {
        throw new Error(`Not a date and time this can read: ${date} ${time}`);
    }

    const firstGuess = new Date(asIfUtc - zoneOffsetMs(timeZone, new Date(asIfUtc)));
    const corrected = new Date(asIfUtc - zoneOffsetMs(timeZone, firstGuess));

    // The correction is right whenever the wall clock exists. When it does not
    // -- the hour a spring-forward skips -- the two passes disagree, and the
    // later of them is the one past the gap. Which pass that is depends on the
    // sign of the offset: taking `firstGuess` unconditionally shifts forward
    // west of UTC and *backward* everywhere else, reporting a departure earlier
    // than any instant the schedule could name. London is close enough to the
    // meridian to make that reachable from the airport data as it stands.
    if (departureInOriginZone(corrected, timeZone).time === time) return corrected;
    return new Date(Math.max(firstGuess.getTime(), corrected.getTime()));
}

/**
 * The instants bounding a calendar day at an airport, as `[start, end)`.
 *
 * A customer searching for the 16th means the 16th where they are standing.
 * With departures stored as instants, a UTC day is the wrong window whenever
 * the origin's local date differs from the UTC one: a 22:00 Miami departure is
 * 02:00Z the next day, so a UTC-day query missed it on every single occurrence
 * and the route could not be booked at all (#84).
 *
 * Half-open, because a closed upper bound has to name the last representable
 * millisecond and a day is not always 24 hours long anyway -- a daylight-saving
 * day is 23 or 25.
 */
export function airportDayBounds(date: string, timeZone: string | null | undefined): {
    start: Date;
    end: Date;
} {
    const zone = timeZone ?? 'UTC';
    const nextDay = new Date(`${date}T00:00:00.000Z`);
    nextDay.setUTCDate(nextDay.getUTCDate() + 1);

    return {
        start: airportLocalInstant(date, '00:00', zone),
        end: airportLocalInstant(nextDay.toISOString().slice(0, 10), '00:00', zone),
    };
}

/**
 * A flight's departure, read at the airport it leaves from.
 *
 * The convenience form for rendering: takes the route label the flight already

 * The convenience form for rendering: takes the route label the flight already
 * carries and looks its zone up, so no screen has to remember to. Every screen
 * used `toLocaleDateString()` before, which renders in whatever timezone the
 * viewer's browser is set to -- so the same flight read differently depending
 * on where the person looking at it happened to be sitting, which #84's
 * acceptance criteria rule out.
 */
export function flightDeparture(flight: {
    departureDate: Date | string;
    from: string;
}): LocalDeparture {
    return departureInOriginZone(flight.departureDate, airportTimeZoneFor(flight.from));
}

/** A departure as the airport it leaves from sees it. */
export interface LocalDeparture {
    /** `YYYY-MM-DD` at the origin, for comparing and for date inputs. */
    date: string;
    /** `HH:MM` on the origin's 24-hour clock. */
    time: string;
    /** `Aug 16, 2026`, for reading. */
    readableDate: string;
    /** `PDT`, `GMT+9` -- whatever that zone was called at that instant. */
    zoneLabel: string;
}

const READABLE_DATE: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
};

/**
 * A departure instant, read in the origin airport's timezone.
 *
 * `timeZone` is null for a place with no airport record, which falls back to
 * UTC -- the same answer the application gave everywhere before, and a
 * degradation rather than a failure.
 *
 * The zone label matters as much as the time. A bare "08:00" on a booking is
 * not information: the customer cannot tell whose clock it is on, and for an
 * international leg the answer is rarely theirs.
 */
export function departureInOriginZone(
    departure: Date | string,
    timeZone: string | null | undefined,
): LocalDeparture {
    const instant = departure instanceof Date ? departure : new Date(departure);
    const zone = timeZone ?? 'UTC';

    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: zone,
        hour12: false,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
    }).formatToParts(instant);
    const at = (type: Intl.DateTimeFormatPartTypes) =>
        parts.find(part => part.type === type)!.value;

    const hour = String(Number(at('hour')) % 24).padStart(2, '0');

    return {
        date: `${at('year')}-${at('month')}-${at('day')}`,
        time: `${hour}:${at('minute')}`,
        readableDate: new Intl.DateTimeFormat('en-US', { ...READABLE_DATE, timeZone: zone })
            .format(instant),
        zoneLabel: new Intl.DateTimeFormat('en-US', { timeZone: zone, timeZoneName: 'short' })
            .formatToParts(instant)
            .find(part => part.type === 'timeZoneName')!.value,
    };
}

/** A flight's arrival, read at the airport it lands in. */
export interface LocalArrival extends LocalDeparture {
    /**
     * How many calendar days later it lands, at the destination. Almost always
     * 0 or 1; eastbound long-haul can be 1 even on a short flight, and a
     * westbound crossing of the date line can be negative.
     */
    dayOffset: number;
}

/**
 * When a flight lands, as an instant.
 *
 * Departure plus elapsed minutes. No timezone is involved and none can be: an
 * elapsed duration is the same number of minutes wherever either end of the
 * route is, which is exactly why the duration is what gets stored (#84).
 */
export function arrivalInstant(departure: Date | string, durationMinutes: number): Date {
    const instant = departure instanceof Date ? departure : new Date(departure);
    return new Date(instant.getTime() + durationMinutes * 60_000);
}

/**
 * A flight's arrival, read at the destination -- with how many days later that
 * is than the departure was at the origin.
 *
 * The offset is the `+1` a timetable prints, and it is a comparison between two
 * *local* dates in two different zones. It cannot be had by subtracting
 * instants: a Tokyo to San Francisco flight lands on the same calendar date it
 * left, hours earlier by the clock, while a shorter New York to London hop
 * lands the next day.
 */
export function flightArrival(flight: {
    departureDate: Date | string;
    durationMinutes: number;
    from: string;
    to: string;
}): LocalArrival {
    const arrival = arrivalInstant(flight.departureDate, flight.durationMinutes);
    const atDestination = departureInOriginZone(arrival, airportTimeZoneFor(flight.to));
    const atOrigin = departureInOriginZone(flight.departureDate, airportTimeZoneFor(flight.from));

    return { ...atDestination, dayOffset: calendarDaysBetween(atOrigin.date, atDestination.date) };
}

/**
 * Whole calendar days from one `YYYY-MM-DD` to another.
 *
 * Both are read as UTC midnights purely to count days between them; neither is
 * an instant and no zone applies. Doing it any other way -- subtracting the two
 * flights' instants, say -- answers a different question and gets the marker
 * wrong for every route that crosses a date boundary without taking 24 hours.
 */
function calendarDaysBetween(from: string, to: string): number {
    const start = Date.parse(`${from}T00:00:00.000Z`);
    const end = Date.parse(`${to}T00:00:00.000Z`);
    return Math.round((end - start) / 86_400_000);
}

/** `7h 05m`, the way a timetable states elapsed time. */
export function durationLabel(durationMinutes: number): string {
    const hours = Math.floor(durationMinutes / 60);
    const minutes = durationMinutes % 60;
    return `${hours}h ${String(minutes).padStart(2, '0')}m`;
}

export type FlightPhase = 'UPCOMING' | 'DEPARTED' | 'ARRIVED' | 'DELAYED' | 'CANCELLED';

interface FlightPhaseInput {
    departureDate: Date | string;
    durationMinutes?: number | null;
    status: 'ON_TIME' | 'DELAYED' | 'CANCELLED';
}

/**
 * The phase a status-board row may truthfully derive from its schedule.
 *
 * Delayed and cancelled are airline-set facts, so the clock never overwrites
 * them. An ordinary occurrence advances through its scheduled instants. A
 * flight with no stated duration can pass departure, but cannot be called
 * arrived without inventing an arrival instant (#84).
 */
export function flightPhaseAt(flight: FlightPhaseInput, renderedAt: number): FlightPhase {
    if (flight.status === 'CANCELLED') return 'CANCELLED';
    if (flight.status === 'DELAYED') return 'DELAYED';

    const departureAt = new Date(flight.departureDate).getTime();
    if (renderedAt < departureAt) return 'UPCOMING';
    if (flight.durationMinutes === null || flight.durationMinutes === undefined) {
        return 'DEPARTED';
    }

    const arrivalAt = departureAt + flight.durationMinutes * 60_000;
    return renderedAt < arrivalAt ? 'DEPARTED' : 'ARRIVED';
}

import type { Metadata } from 'next';
